import { bangla } from './translations.ts';

export type Language = 'en' | 'bn';
export type TranslationValues = Record<string, string | number>;
export const LANGUAGE_STORAGE_KEY = 'daily-expense-language';

export function localizeDigits(text: string, language: Language): string {
  return language === 'bn' ? text.replace(/\d/g, (digit) => '০১২৩৪৫৬৭৮৯'[Number(digit)]!) : text;
}

/** Analytics labels are generated by the API in English; preserve their bucket boundaries. */
export function localizePeriodLabel(label: string, language: Language): string {
  if (language === 'en') return label;
  const months: Record<string, string> = {
    Jan: 'জানু',
    Feb: 'ফেব',
    Mar: 'মার্চ',
    Apr: 'এপ্রিল',
    May: 'মে',
    Jun: 'জুন',
    Jul: 'জুলাই',
    Aug: 'আগস্ট',
    Sep: 'সেপ্টে',
    Oct: 'অক্টো',
    Nov: 'নভে',
    Dec: 'ডিসে',
  };
  return localizeDigits(
    label.replace(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec|Wk)\b/g, (part) =>
      part === 'Wk' ? 'সপ্তাহ' : months[part]!,
    ),
    language,
  );
}

export function translate(language: Language, key: string, values: TranslationValues = {}): string {
  const template = language === 'bn' ? (bangla[key] ?? key) : key;
  return template.replace(/\{(\w+)\}/g, (placeholder, name: string) => {
    const value = values[name];
    // Keep names, filenames and other user-provided strings exactly as entered.
    return value === undefined
      ? placeholder
      : typeof value === 'number'
        ? localizeDigits(String(value), language)
        : value;
  });
}
